import java.util.HashSet;
import java.util.Set;

public static int firstRepeated(int[] nums) {
    Set<Integer> seen = new HashSet<>();
    for (int value : nums) {
        if (!seen.add(value)) {
            return value;
        }
    }
    return -1;
}
